insert into A1_MFG.CAPACITY_PRODUCTMIX_UPLOAD(TECH,PRODUCT,PRODUCT_MIX,ENG_QTY,TOTAL_QTY,UPDATE_USER,UPDATE_TIME,MODE_TYPE,SHIFT_MONTH,PRODUCT_MIX_N1A1,PRODUCT_MIX_N1A3,ENG_QTY_N1A1,ENG_QTY_N1A3) SELECT B.TECH,A.PRODUCT,A.PRODUCT_MIX,A.ENG_QTY,NVL(A.PRODUCT_MIX,0) + NVL(A.ENG_QTY,0) TOTAL_QTY,A.UPDATE_USER ,A.UPDATE_TIME,A.MODE_TYPE,A.SHIFT_MONTH ,A.PRODUCT_MIX_N1A1,A.PRODUCT_MIX_N1A3,A.ENG_QTY_N1A1,A.ENG_QTY_N1A3 FROM( SELECT PRODUCT ,NVL(PRODUCT_MIX,NVL(PRODUCT_MIX_N1A1,0)+NVL(PRODUCT_MIX_N1A3,0)) PRODUCT_MIX ,NVL(ENG_QTY,NVL(ENG_QTY_N1A1,0)+NVL(ENG_QTY_N1A3,0)) ENG_QTY ,UPDATE_USER,SUBSTR(MODE_TYPE,1,INSTR(MODE_TYPE,'-')-1)SHIFT_MONTH ,SUBSTR(MODE_TYPE,INSTR(MODE_TYPE,'-')+1)MODE_TYPE,UPDATE_TIME ,PRODUCT_MIX_N1A1,PRODUCT_MIX_N1A3,ENG_QTY_N1A1,ENG_QTY_N1A3 FROM(
SELECT #{item.PRODUCT,jdbcType=VARCHAR} PRODUCT ,#{username,jdbcType=VARCHAR} UPDATE_USER ,#{mode,jdbcType=VARCHAR} MODE_TYPE ,#{item.PRODUCT_MIX_N1A1,jdbcType=INTEGER} PRODUCT_MIX_N1A1 ,#{item.PRODUCT_MIX_N1A3,jdbcType=INTEGER} PRODUCT_MIX_N1A3 ,#{item.ENG_QTY_N1A1,jdbcType=INTEGER} ENG_QTY_N1A1 ,#{item.ENG_QTY_N1A3,jdbcType=INTEGER} ENG_QTY_N1A3 ,#{item.ENG_QTY,jdbcType=INTEGER} ENG_QTY ,#{item.PRODUCT_MIX,jdbcType=INTEGER} PRODUCT_MIX ,SYSDATE UPDATE_TIME FROM DUAL
) )A LEFT JOIN ( SELECT DISTINCT PRODG1,TECH FROM A3MFGYW1.PRODG_INFO )B ON A.PRODUCT = B.PRODG1

merge into A1_MFG.CAPACITY_EQPGINFO_UPLOAD A using ( SELECT A.EQP_G,A.BATCH_SIZE,A.STD_EQP_ID,ROUND(A.A12_STD_COUNT,2) A12_STD_COUNT,ROUND(A.A3_STD_COUNT,2) A3_STD_COUNT ,ROUND(A.A12_ACT_COUNT,2) A12_ACT_COUNT,ROUND(A.A3_ACT_COUNT,2) A3_ACT_COUNT ,A.UPDATE_USER,A.UPDATE_TIME,A.F_COMMENT,ROUND(A.A12_SELF_COUNT,2)A12_SELF_COUNT,ROUND(A.A3_SELF_COUNT,2)A3_SELF_COUNT ,SUBSTR(A.MODE_TYPE,1,INSTR(A.MODE_TYPE,'-')-1)SHIFT_MONTH,SUBSTR(A.MODE_TYPE,INSTR(A.MODE_TYPE,'-')+1)MODE_TYPE ,ROUND(B.OEE_TARGET,5) STD_OEE_TARGET,B.MODULE FROM(
SELECT TRIM(#{item.EQP_G,jdbcType=VARCHAR}) EQP_G ,#{item.BATCH_SIZE,jdbcType=INTEGER} BATCH_SIZE ,#{item.STD_EQP_ID,jdbcType=VARCHAR} STD_EQP_ID ,#{item.A12_STD_COUNT,jdbcType=FLOAT} A12_STD_COUNT ,#{item.A3_STD_COUNT,jdbcType=FLOAT} A3_STD_COUNT ,#{item.A12_ACT_COUNT,jdbcType=FLOAT} A12_ACT_COUNT ,#{item.A3_ACT_COUNT,jdbcType=FLOAT} A3_ACT_COUNT ,#{username,jdbcType=VARCHAR} UPDATE_USER ,#{mode,jdbcType=VARCHAR} MODE_TYPE ,#{item.F_COMMENT,jdbcType=VARCHAR} F_COMMENT ,#{item.A12_SELF_COUNT,jdbcType=FLOAT} A12_SELF_COUNT ,#{item.A3_SELF_COUNT,jdbcType=FLOAT} A3_SELF_COUNT ,SYSDATE UPDATE_TIME FROM DUAL
)A JOIN ( -- for comment STD_EQP_ID 无OEE的不更新，上传 SELECT EQP_ID,EQP_G,MAX(OEE_TARGET)OEE_TARGET,MAX(MODULE)MODULE FROM A3MFGYW1.T_OPD_EFF_UP_UT_TARGET WHERE SHIFT_DATE = TO_CHAR(SYSDATE-7.5/24,'YYYYMMDD') AND EQP_ID IS NOT NULL GROUP BY EQP_ID,EQP_G ) B ON A.STD_EQP_ID = B.EQP_ID AND A.EQP_G = B.EQP_G )B ON (A.MODULE = B.MODULE AND A.EQP_G = B.EQP_G AND A.MODE_TYPE =B.MODE_TYPE AND A.SHIFT_MONTH = B.SHIFT_MONTH) WHEN MATCHED THEN UPDATE SET A.UPDATE_USER = B.UPDATE_USER ,A.UPDATE_TIME = B.UPDATE_TIME ,A.BATCH_SIZE = CASE WHEN B.BATCH_SIZE IS NOT NULL THEN B.BATCH_SIZE ELSE A.BATCH_SIZE END ,A.STD_EQP_ID = CASE WHEN B.STD_EQP_ID IS NOT NULL THEN B.STD_EQP_ID ELSE A.STD_EQP_ID END ,A.A12_STD_COUNT = CASE WHEN B.A12_STD_COUNT IS NOT NULL THEN B.A12_STD_COUNT ELSE A.A12_STD_COUNT END ,A.A3_STD_COUNT = CASE WHEN B.A3_STD_COUNT IS NOT NULL THEN B.A3_STD_COUNT ELSE A.A3_STD_COUNT END ,A.A12_ACT_COUNT = CASE WHEN B.A12_ACT_COUNT IS NOT NULL THEN B.A12_ACT_COUNT ELSE A.A12_ACT_COUNT END ,A.A3_ACT_COUNT = CASE WHEN B.A3_ACT_COUNT IS NOT NULL THEN B.A3_ACT_COUNT ELSE A.A3_ACT_COUNT END ,A.STD_OEE_TARGET = CASE WHEN B.STD_OEE_TARGET IS NOT NULL THEN B.STD_OEE_TARGET ELSE A.STD_OEE_TARGET END ,A.F_COMMENT = CASE WHEN B.F_COMMENT IS NOT NULL THEN B.F_COMMENT ELSE A.F_COMMENT END ,A.A12_SELF_COUNT = CASE WHEN B.A12_SELF_COUNT IS NOT NULL THEN B.A12_SELF_COUNT ELSE A.A12_SELF_COUNT END ,A.A3_SELF_COUNT = CASE WHEN B.A3_SELF_COUNT IS NOT NULL THEN B.A3_SELF_COUNT ELSE A.A3_SELF_COUNT END WHEN NOT MATCHED THEN INSERT (MODULE,EQP_G,BATCH_SIZE,STD_EQP_ID,A12_STD_COUNT,A3_STD_COUNT,A12_ACT_COUNT,A3_ACT_COUNT,STD_OEE_TARGET,MODE_TYPE,UPDATE_USER,UPDATE_TIME,SHIFT_MONTH,F_COMMENT,A12_SELF_COUNT,A3_SELF_COUNT) VALUES (B.MODULE,B.EQP_G,B.BATCH_SIZE,B.STD_EQP_ID,B.A12_STD_COUNT,B.A3_STD_COUNT,B.A12_ACT_COUNT,B.A3_ACT_COUNT,B.STD_OEE_TARGET,B.MODE_TYPE,B.UPDATE_USER,B.UPDATE_TIME,B.SHIFT_MONTH,B.F_COMMENT,B.A12_SELF_COUNT,B.A3_SELF_COUNT)

