update A1_MFG.CAPACITY_EQPGINFO_UPLOAD
set
F_COMMENT = #{fComment,jdbcType=VARCHAR}
,BATCH_SIZE = NVL(#{batchSize,jdbcType=INTEGER},1)
,A12_STD_COUNT = #{a12StdCount,jdbcType=FLOAT}
,A3_STD_COUNT = #{a3StdCount,jdbcType=FLOAT}
,A12_ACT_COUNT = #{a12ActCount,jdbcType=FLOAT}
,A3_ACT_COUNT = #{a3ActCount,jdbcType=FLOAT}
,A12_SELF_COUNT = #{a12SelfCount,jdbcType=FLOAT}
,A3_SELF_COUNT = #{a3SelfCount,jdbcType=FLOAT}
,UPDATE_USER = #{username,jdbcType=VARCHAR}
,UPDATE_TIME = SYSDATE
where EQP_G = #{eqpg,jdbcType=VARCHAR} AND SHIFT_MONTH||'-'||MODE_TYPE = #{mode,jdbcType=VARCHAR}

update A1_MFG.CAPACITY_EQPGINFO_UPLOAD
set EQPG_COMMENT = #{eqpgComment,jdbcType=VARCHAR}
,EQPG_COMMENT2 = #{eqpgComment2,jdbcType=VARCHAR}
,UPDATE_USER = #{username,jdbcType=VARCHAR},UPDATE_TIME = SYSDATE
where EQP_G = #{eqpg,jdbcType=VARCHAR} AND SHIFT_MONTH||'-'||MODE_TYPE = #{mode,jdbcType=VARCHAR}

