    UPDATE A1_MFG.CAPACITY_RC_CONSTRAINTS
    SET
    CONSTRAINTS = #{CONSTRAINTS,jdbcType=VARCHAR}
    ,ACTION = #{ACTION,jdbcType=VARCHAR}
    ,SPONSOR = #{SPONSOR,jdbcType=VARCHAR}
    ,DUE_DATE = TO_DATE(#{DUE_DATE,jdbcType=VARCHAR},'YYYYMMDD')
    ,UPDATE_USER = #{UPDATE_USER,jdbcType=VARCHAR}
    ,UPDATE_TIME = SYSDATE
    ,FIRST_DUE_DATE = CASE WHEN FIRST_DUE_DATE IS NULL THEN TO_DATE(#{DUE_DATE,jdbcType=VARCHAR},'YYYYMMDD') ELSE FIRST_DUE_DATE  END
    ,DUE_DATE_COMMENT = CASE WHEN DUE_DATE_COMMENT IS NULL THEN #{DUE_DATE,jdbcType=VARCHAR}
    WHEN DUE_DATE_COMMENT LIKE '%'||#{DUE_DATE,jdbcType=VARCHAR} THEN DUE_DATE_COMMENT
     ELSE DUE_DATE_COMMENT || ' => ' || #{DUE_DATE,jdbcType=VARCHAR} END
    ,DONE_TIME = CASE WHEN #{STATUS,jdbcType=VARCHAR} = 'Done' AND DONE_TIME IS NULL THEN SYSDATE ELSE DONE_TIME END
WHERE CONSTRAINTS_ID = #{CONSTRAINTS_ID}

MERGE INTO A1_MFG.CAPACITY_EQPGINFO_UPLOAD A USING (
SELECT #{item.eqpg,jdbcType=VARCHAR} EQP_G ,#{source,jdbcType=VARCHAR} MODE_TYPE ,#{item.uploadComment1,jdbcType=VARCHAR} EQPG_COMMENT ,#{item.uploadComment2,jdbcType=VARCHAR} EQPG_COMMENT2 ,#{username,jdbcType=VARCHAR} UPDATE_USER ,SYSDATE UPDATE_TIME FROM DUAL
) B ON (A.EQP_G = B.EQP_G AND A.SHIFT_MONTH||'-'||A.MODE_TYPE = B.MODE_TYPE) WHEN MATCHED THEN UPDATE SET A.EQPG_COMMENT = B.EQPG_COMMENT ,A.EQPG_COMMENT2 = B.EQPG_COMMENT2 ,A.UPDATE_USER = B.UPDATE_USER ,A.UPDATE_TIME = B.UPDATE_TIME
